#!/usr/bin/env bash
# Downloads every scene image into ./images/ as NNN_start_end.png,
# plus the locked main-character reference as 000_character.png.
set -euo pipefail
cd "$(dirname "$0")"
mkdir -p images
dl() { curl -fSL --retry 4 -o "images/$1" "$2" && echo "  $1"; }

